def apex_stars_to_points(apps, schema_editor):
    """Apex lama memakai bintang tanpa batas; kini Apex Points (1★ lama = 10 poin)."""
    from gamification.ranking import RankState, ladder_points
    PlayerRank = apps.get_model("gamification", "PlayerRank")
    for r in PlayerRank.objects.filter(tier="apex"):
        r.apex_points, r.stars = r.stars * 10, 0
        r.points = ladder_points(RankState("apex", None, 0, r.win_streak, r.apex_points))
        r.save(update_fields=["apex_points", "stars", "points"])


